import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"Guía de uso","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/usage.md","filePath":"es/guide/usage.md","lastUpdated":1793173149000}`),a={name:`es/guide/usage.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="guia-de-uso" tabindex="-1">Guía de uso <a class="header-anchor" href="#guia-de-uso" aria-label="Permalink to “Guía de uso”">​</a></h1><h2 id="jugabilidad-basica" tabindex="-1">Jugabilidad básica <a class="header-anchor" href="#jugabilidad-basica" aria-label="Permalink to “Jugabilidad básica”">​</a></h2><h3 id="objetivo" tabindex="-1">Objetivo <a class="header-anchor" href="#objetivo" aria-label="Permalink to “Objetivo”">​</a></h3><p>Rellena una cuadrícula de 9×9 de modo que cada <strong>fila</strong>, cada <strong>columna</strong> y cada una de las nueve <strong>cajas</strong> de 3×3 contengan todos los dígitos del 1 al 9 exactamente una vez. No se permite repetir ningún número dentro de una misma unidad.</p><h3 id="como-jugar" tabindex="-1">Cómo jugar <a class="header-anchor" href="#como-jugar" aria-label="Permalink to “Cómo jugar”">​</a></h3><ul><li><strong>Colocar un número</strong>: toca o haz clic en una celda vacía y luego toca un dígito del teclado numérico de la parte inferior de la pantalla.</li><li><strong>Notas a lápiz (candidatos)</strong>: activa el modo Lápiz y toca las celdas para escribir pequeños dígitos candidatos. Resulta útil para ir anotando las posibilidades.</li><li><strong>Borrar</strong>: toca el botón Borrar para vaciar el valor de una celda (o las marcas a lápiz si estás en modo lápiz).</li><li><strong>Pista</strong>: toca Pista para revelar el valor correcto de una celda.</li><li><strong>Deshacer</strong>: toca Deshacer para revertir tu último movimiento (con historial completo de deshacer).</li></ul><h3 id="niveles-de-dificultad" tabindex="-1">Niveles de dificultad <a class="header-anchor" href="#niveles-de-dificultad" aria-label="Permalink to “Niveles de dificultad”">​</a></h3><p>Cada nivel de dificultad determina cuántas celdas vienen rellenadas (dadas) al empezar:</p><table tabindex="0"><thead><tr><th>Nivel</th><th>Celdas dadas</th><th>Ideal para</th></tr></thead><tbody><tr><td>Fácil</td><td>45</td><td>Principiantes y partidas rápidas</td></tr><tr><td>Medio</td><td>36</td><td>Jugadores ocasionales</td></tr><tr><td>Difícil</td><td>31</td><td>Solucionadores habituales</td></tr><tr><td>Experto</td><td>27</td><td>Jugadores con experiencia</td></tr><tr><td>Maestro</td><td>24</td><td>Maestros de los puzles</td></tr></tbody></table><p><img src="/screenshot-mac-main.png" alt="Tablero de juego de Sudoku en el Mac"></p><h2 id="controles-del-juego" tabindex="-1">Controles del juego <a class="header-anchor" href="#controles-del-juego" aria-label="Permalink to “Controles del juego”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ul><li><strong>Toca</strong> una celda vacía para seleccionarla</li><li><strong>Toca un número</strong> del teclado numérico para colocarlo</li><li><strong>Activa el modo Lápiz</strong> para escribir o borrar notas de candidatos</li><li><strong>Usa Borrar</strong> para vaciar una celda</li><li><strong>Usa Pista</strong> cuando te quedes atascado</li><li><strong>Usa Deshacer</strong> para revertir movimientos</li></ul><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ul><li><strong>Haz clic con el botón izquierdo</strong> en una celda vacía para seleccionarla</li><li><strong>Escribe una tecla numérica (1–9)</strong> o haz clic en el teclado en pantalla para colocar el número</li><li><strong>Activa el modo Lápiz</strong> para las notas de candidatos</li><li><strong>Atajos de teclado</strong>: <ul><li><code>⌘N</code> — Nueva partida</li><li><code>⌘Z</code> — Deshacer</li><li><code>⌘1</code> a <code>⌘5</code> — Iniciar una nueva partida en cada nivel de dificultad</li></ul></li></ul><p><img src="/screenshot-iphone-main.png" alt="Pantalla de inicio de Sudoku en el iPhone"></p><p><img src="/screenshot-ipad-main.png" alt="Pantalla de inicio de Sudoku en el iPad"></p><h2 id="funciones-inteligentes" tabindex="-1">Funciones inteligentes <a class="header-anchor" href="#funciones-inteligentes" aria-label="Permalink to “Funciones inteligentes”">​</a></h2><h3 id="sistema-de-notas-a-lapiz" tabindex="-1">Sistema de notas a lápiz <a class="header-anchor" href="#sistema-de-notas-a-lapiz" aria-label="Permalink to “Sistema de notas a lápiz”">​</a></h3><p>Cuando activas el modo Lápiz, puedes escribir pequeños dígitos candidatos en las celdas vacías. El sistema inteligente de lápiz:</p><ul><li><strong>Borra automáticamente las marcas a lápiz relacionadas</strong>: cuando colocas un número definitivo, las marcas a lápiz de ese dígito se eliminan automáticamente de todas las celdas de la misma fila, columna y caja.</li><li><strong>Alternar por celda</strong>: cambia entre el modo de entrada y el modo lápiz en cualquier momento.</li></ul><h3 id="comprobacion-de-errores" tabindex="-1">Comprobación de errores <a class="header-anchor" href="#comprobacion-de-errores" aria-label="Permalink to “Comprobación de errores”">​</a></h3><p>El resaltado opcional de errores muestra las entradas incorrectas en rojo, lo que te ayuda a aprender sin desvelar el puzle.</p><h3 id="desafio-diario" tabindex="-1">Desafío diario <a class="header-anchor" href="#desafio-diario" aria-label="Permalink to “Desafío diario”">​</a></h3><p>Cada día se genera un puzle nuevo de nivel Maestro. El progreso de tu desafío diario se registra en Estadísticas, con una vista de calendario que muestra tu racha.</p><h3 id="estadisticas" tabindex="-1">Estadísticas <a class="header-anchor" href="#estadisticas" aria-label="Permalink to “Estadísticas”">​</a></h3><p>Sigue tu recorrido por el Sudoku:</p><ul><li>Partidas totales jugadas y porcentaje de victorias</li><li>Racha actual y mejor racha</li><li>Desglose por dificultad: partidas ganadas, mejor tiempo, tiempo medio</li><li>Calendario del desafío diario con indicadores de finalización</li></ul><p><img src="/screenshot-mac-settings.png" alt="Estadísticas de Sudoku en el Mac"></p><h2 id="temas" tabindex="-1">Temas <a class="header-anchor" href="#temas" aria-label="Permalink to “Temas”">​</a></h2><p>Elige entre ocho temas de color preciosos en Ajustes:</p><table tabindex="0"><thead><tr><th>Tema</th><th>Estilo</th></tr></thead><tbody><tr><td>Classic</td><td>Blanco limpio con detalles en azul</td></tr><tr><td>Midnight</td><td>Modo oscuro con azules profundos</td></tr><tr><td>Paper</td><td>Textura cálida de pergamino</td></tr><tr><td>Forest</td><td>Verdes naturales</td></tr><tr><td>Ocean</td><td>Azules serenos de mar</td></tr><tr><td>Sunset</td><td>Degradados cálidos de naranja</td></tr><tr><td>Lavender</td><td>Tonos suaves de violeta</td></tr><tr><td>Rose</td><td>Elegante paleta de rosas</td></tr></tbody></table><h2 id="sincronizacion-con-icloud" tabindex="-1">Sincronización con iCloud <a class="header-anchor" href="#sincronizacion-con-icloud" aria-label="Permalink to “Sincronización con iCloud”">​</a></h2><p>Cuando has iniciado sesión en iCloud en tu dispositivo:</p><ul><li>Las partidas guardadas se sincronizan automáticamente: continúa en cualquier dispositivo</li><li>Las estadísticas y los ajustes se mantienen sincronizados</li><li>El progreso del desafío diario se traslada entre dispositivos</li><li>Requiere iOS/iPadOS 16 o posterior o macOS 15 o posterior</li></ul><h2 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h2><p>Conecta con Game Center para:</p><ul><li>Competir en las <strong>clasificaciones</strong> por los mejores tiempos de finalización en cada dificultad</li><li>Ganar <strong>logros</strong>: First Solve, Easy/Medium/Hard/Expert/Master Clear, Flawless (sin pistas ni errores)</li></ul><h2 id="imprimir-puzles-mac" tabindex="-1">Imprimir puzles (Mac) <a class="header-anchor" href="#imprimir-puzles-mac" aria-label="Permalink to “Imprimir puzles (Mac)”">​</a></h2><p>En Mac, imprime puzles directamente desde la app:</p><ol><li>Abre el diálogo <strong>Imprimir</strong> desde la barra de herramientas</li><li>Selecciona el nivel de dificultad (de Fácil a Maestro)</li><li>Activa «Incluir respuestas» si lo deseas</li><li>Haz clic en <strong>Imprimir</strong></li></ol><p>¡Perfecto para resolver sin conexión con papel y lápiz!</p><h2 id="efectos-de-sonido" tabindex="-1">Efectos de sonido <a class="header-anchor" href="#efectos-de-sonido" aria-label="Permalink to “Efectos de sonido”">​</a></h2><p>Sudoku incluye sutiles efectos de sonido:</p><ul><li>Confirmación al colocar un número</li><li>Pista revelada</li><li>Aviso de error</li><li>Celebración de victoria</li></ul><p>Activa o desactiva el sonido en <strong>Ajustes → Sonido</strong>.</p><h2 id="consejos-y-trucos" tabindex="-1">Consejos y trucos <a class="header-anchor" href="#consejos-y-trucos" aria-label="Permalink to “Consejos y trucos”">​</a></h2><ul><li><strong>Empieza por lo que ya está dado</strong>: revisa las filas, columnas y cajas que ya tienen muchos números rellenados.</li><li><strong>Usa las notas a lápiz</strong>: resultan especialmente útiles en las dificultades Difícil, Experto y Maestro.</li><li><strong>Busca solteros desnudos</strong>: si una celda tiene un solo candidato posible, colócalo.</li><li><strong>Busca solteros ocultos</strong>: si un dígito solo puede ir en un lugar dentro de una fila, columna o caja, colócalo ahí.</li><li><strong>Usa las pistas con moderación</strong>: van muy bien para aprender, pero completar un puzle sin pistas sienta mucho mejor.</li><li><strong>Construye tu racha diaria</strong>: el desafío diario es una forma estupenda de practicar con constancia.</li></ul>`,48)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};